const store = {};

function main(req) {
  const limit = parseInt(env('RATE_LIMIT', '10'));
  const windowSec = parseInt(env('RATE_WINDOW_SEC', '60'));
  const clientIP = (req.headers || {})['X-Forwarded-For'] || (req.headers || {})['x-forwarded-for'] || 'unknown';
  const now = Math.floor(Date.now() / 1000);
  const windowKey = `${clientIP}:${Math.floor(now / windowSec)}`;

  if (!store[windowKey]) {
    store[windowKey] = { count: 0, reset: (Math.floor(now / windowSec) + 1) * windowSec };
    // Cleanup old windows
    for (const k of Object.keys(store)) {
      if (store[k].reset < now) delete store[k];
    }
  }

  store[windowKey].count++;
  const remaining = Math.max(0, limit - store[windowKey].count);
  const resetAt = store[windowKey].reset;

  const headers = {
    'X-RateLimit-Limit': String(limit),
    'X-RateLimit-Remaining': String(remaining),
    'X-RateLimit-Reset': String(resetAt)
  };

  if (store[windowKey].count > limit) {
    return {
      status: 429,
      headers: { ...headers, 'Retry-After': String(resetAt - now) },
      body: jsonStringify({ error: 'rate limit exceeded', retry_after: resetAt - now })
    };
  }

  // Forward to actual logic
  const body = jsonParse(req.body, {});
  return {
    status: 200,
    headers,
    body: jsonStringify({
      message: 'request allowed',
      client: clientIP,
      remaining,
      data: body
    })
  };
}
